    # Each external marker's quadrant indicates the destination corner of
    # the same-colored marker inside the framed rectangle.
    dest = {}
    for r, c, v in outside:
        dest[v] = (0 if r < r0 else 1, 0 if c < c0 else 1)

    def variants(mat):
        cur = mat
        for _ in range(4):
            yield cur
            yield [row[::-1] for row in cur]
            cur = [list(row) for row in zip(*cur[::-1])]

    for b in variants(a):
